-- ---------------------------------------------------------------------------
-- Create the baseline project without creating an alignment or acquisition cases.
INSERT INTO public.projects (
    project_code, project_name, project_type, authority, state, districts,
    description, status, is_synthetic, metadata
) VALUES (
    'A-WARD-MH-001',
    'A-Ward GIS parcel baseline / prototype',
    'highway',
    'BhoomiTrack GIS baseline',
    'Maharashtra',
    ARRAY['Mumbai City'],
    'A-Ward GIS parcel baseline / prototype; final coordinated highway alignment pending.',
    'planned',
    TRUE,
    jsonb_build_object(
        'data_class', 'SOURCE_DERIVED_GEOMETRY_SYNTHETIC_ATTRIBUTES',
        'baseline_only', true,
        'alignment_pending', true,
        'synthetic_owner_notice', 'Ownership and other attributes are synthetic prototype data and are not official government records.'
    )
)
ON CONFLICT (project_code) DO UPDATE SET
    project_name = EXCLUDED.project_name,
    project_type = EXCLUDED.project_type,
    description = EXCLUDED.description,
    status = 'planned',
    is_synthetic = TRUE,
    metadata = EXCLUDED.metadata;

-- NULL affected_area_sqm means analysis pending, never unaffected.
INSERT INTO public.project_parcels (project_id, parcel_id, affected_area_sqm, inclusion_reason)
SELECT
    pr.id,
    pa.id,
    NULL,
    'GIS BASELINE ONLY — final alignment and impact analysis pending.'
FROM public.projects pr
JOIN public.parcels pa ON pa.source_ref ->> 'ward' = 'A Ward'
WHERE pr.project_code = 'A-WARD-MH-001'
ON CONFLICT (project_id, parcel_id) DO UPDATE SET
    affected_area_sqm = NULL,
    inclusion_reason = EXCLUDED.inclusion_reason;

COMMIT;

